<script setup>
import { computed, ref, watch } from 'vue'
import { orderHistory, historyCategories, historyTitle, historyDate } from '../services/orderHistory.js'
import { locations } from '../calculation/tracking.js'
const props = defineProps({ session: { type: Object, required: true }, orderNo: { type: [Number, String], required: true } })
const expanded = ref(false), data = ref(null), busy = ref(false), error = ref(''), group = ref('ALL'), product = ref(''), page = ref(0)
let sequence = 0
const categories = computed(() => Object.entries(historyCategories).filter(([key]) => (key !== 'FINANCE' || data.value?.canFinance) && (key !== 'CONTACT' || data.value?.canContacts)))
async function load(reset = false) {
 if (reset) page.value = 0
 const request = ++sequence; busy.value = true; error.value = ''
 try { const result = await orderHistory(props.session.token, `/${props.orderNo}?group=${group.value}&page=${page.value}${product.value ? '&product=' + product.value : ''}`); if (request === sequence) data.value = result }
 catch (e) { if (request === sequence) { error.value = e.message; data.value = null } }
 finally { if (request === sequence) busy.value = false }
}
function toggle() { expanded.value = !expanded.value; if (expanded.value) load(true) }
function turn(delta) { page.value += delta; load() }
watch(() => props.orderNo, () => { sequence++; data.value = null; group.value = 'ALL'; product.value = ''; page.value = 0; if (expanded.value) load() })
</script>
<template><section class="order-history"><button type="button" class="history-toggle" :aria-expanded="expanded" @click="toggle">{{ expanded ? 'Згорнути історію' : 'Історія замовлення' }} №{{ orderNo }}</button><div v-if="expanded" class="history-body"><header><h3>Історія замовлення №{{ orderNo }}</h3><button type="button" :disabled="busy" @click="load(true)">Оновити</button></header><p>Нові події зверху. Показуються наявні записи; незбережені раніше дії не відновлюються.</p><div class="history-filters"><label>Етап<select v-model="group" :disabled="busy" @change="load(true)"><option v-for="[key,label] in categories" :key="key" :value="key">{{ label }}</option></select></label><label>Виріб / версія<select v-model="product" :disabled="busy" @change="load(true)"><option value="">Усе замовлення</option><option v-for="p in data?.products || []" :key="p.id" :value="p.id">{{ p.productName }} · версія {{ p.revision }}{{ p.active === true || Number(p.active) === 1 ? '' : ' (архів)' }}</option></select></label></div><p v-if="busy" role="status">Завантаження…</p><p v-if="error" role="alert">{{ error }}</p><template v-if="data && !busy"><p v-if="data.canFinance">Лише проводки, прямо пов’язані із цим замовленням. Спільні оплати рахунків та аванс клієнта перевіряйте у фінансовій картці; ця стрічка не розраховує борг.</p><p v-if="!data.rows.length">За вибраними фільтрами подій немає.</p><ol><li v-for="row in data.rows" :key="row.eventKey"><time>{{ historyDate(row.happenedAt) }}</time><strong>{{ historyTitle(row) }}</strong><span v-if="row.productName">Виріб: {{ row.productName }}</span><span v-if="row.actor">Виконав: {{ row.actor }}</span><span v-if="row.fromLocation">{{ locations[row.fromLocation] || row.fromLocation }} → {{ locations[row.toLocation] || row.toLocation }}</span><span v-if="row.amount != null">{{ row.direction === 'IN' ? 'Зарахування' : 'Нарахування / списання' }}: {{ Number(row.amount).toLocaleString('uk-UA', { minimumFractionDigits: 2 }) }} грн</span><p v-if="row.note">{{ row.note }}</p></li></ol><nav aria-label="Сторінки історії"><button type="button" :disabled="busy || page === 0" @click="turn(-1)">Новіші</button><span>{{ page + 1 }}</span><button type="button" :disabled="busy || !data.hasMore" @click="turn(1)">Старіші</button></nav></template></div></section></template>
<style scoped>.order-history{margin:12px 0;min-width:0}.history-toggle{width:100%;text-align:left;background:#eef5f6}.history-body{padding:14px;border:1px solid #cbd9df;border-radius:8px}header,nav{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}h3{margin:0}.history-filters{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:grid;gap:6px;min-width:0}button,select{font:inherit;min-height:44px;padding:9px;border:1px solid #b9cbd1;border-radius:7px;max-width:100%;box-sizing:border-box}button{cursor:pointer}button:disabled{opacity:.5}ol{list-style:none;padding:0;margin:14px 0}li{display:grid;gap:5px;border-left:3px solid #32777d;padding:10px 12px;margin:12px 0;background:#f7f9fa;overflow-wrap:anywhere}time{font-size:13px;color:#546574}li p{margin:4px 0;white-space:pre-wrap}[role=alert]{color:#a22}@media(max-width:600px){.history-filters{grid-template-columns:1fr}.history-body{padding:10px}select{font-size:16px;width:100%}}</style>
